     return <Component {...pageProps} />;
   }

   export default MyApp;
   ```

7. Open up another terminal window and start the Next.js development server:

   ```bash
   yarn dev
   ```

8. Navigate to localhost:3000/analysis on your browser to test the sentiment analysis feature.

