using namespace std;

int countWord(string filename, string word) {
    int count = 0;

    // Open the specified file
    ifstream infile(filename);

    if (!infile.is_open()) {
        cerr << "Error: cannot open the file." << endl;
        return -1;   // Return error code (-1)
    }

    while (infile.good()) {   // Loop until end-of-file reached
        string line;

        getline(infile, line);   // Read one line at a time from the file

        size_t pos = line.find(word);            // Search for the target word in current line

